def dispatch_to_series(left, right, func, str_rep=None, axis=None):
    """
    Evaluate the frame operation func(left, right) by evaluating
    column-by-column, dispatching to the Series implementation.

    Parameters
    ----------
    left : DataFrame
    right : scalar or DataFrame
    func : arithmetic or comparison operator
    str_rep : str or None, default None
    axis : {None, 0, 1, "index", "columns"}

    Returns
    -------
    DataFrame
    """
    import pandas.core.computation.expressions as expressions

    right = lib.item_from_zerodim(right)
    if lib.is_scalar(right) or np.ndim(right) == 0:
        def column_op(a, b):
            if isinstance(b, pd.Timedelta):
                b = pd.Timedelta(0)
            return {i: func(a.iloc[:, i], b) for i in range(len(a.columns))}
    elif isinstance(right, ABCDataFrame):
        if not isinstance(right, pd.DataFrame) and right.empty:
            return left._constructor({col: right.dtype for col in left.columns}, index=left.index)
        assert right._indexed_same(left)

        def column_op(a, b):
            return {i: func(a.iloc[:, i], b.iloc[:, i]) for i in range(len(a.columns))}

    elif isinstance(right, ABCSeries) and axis == "columns":
        assert right.index.equals(left.columns)

        def column_op(a, b):
            result = {}
            for i in range(len(a.columns)):
                if b.iloc[i] is pd.NaT:
                    result[i] = pd.Series([pd.NaT] * len(left), index=left.index)
                else:
                    result[i] = func(a.iloc[:, i], b.iloc[i])
            return result
    elif isinstance(right, ABCSeries):
        assert right.index.equals(left.index)

        def column_op(a, b):
            return {i: func(a.iloc[:, i], b) for i in range(len(a.columns))}
    else:
        raise NotImplementedError(right)

    new_data = expressions.evaluate(column_op, str_rep, left, right)
    return left._constructor(new_data, index=left.index, columns=left.columns)
