    # Note: we use iloc to access columns for compat with cases
    #       with non-unique columns.
    import pandas.core.computation.expressions as expressions

    right = lib.item_from_zerodim(right)

    if isinstance(right, ABCSeries) and right.dtype.kind == 'M':
        # Handle the case when right is a Series with timedelta dtype
        # and contains NaT values
        if right.hasnans:
            # Convert NaT values in right to NaN
            right = right.apply(lambda x: np.nan if pd.isnull(x) else x)
            # Perform the operation after converting NaT values
            new_data = left * right
        else:
            # If there are no NaT values, proceed with the original logic
            new_data = left * right
    elif lib.is_scalar(right) or np.ndim(right) == 0:

