def dispatch_to_series(left, right, func, str_rep=None, axis=None):
    """
    Evaluate the frame operation func(left, right) by evaluating
    column-by-column, dispatching to the Series implementation.

    Parameters
    ----------
    left : DataFrame
    right : scalar or DataFrame
    func : arithmetic or comparison operator
    str_rep : str or None, default None
    axis : {None, 0, 1, "index", "columns"}

    Returns
    -------
    DataFrame
    """
    # Import necessary modules
    import pandas.core.computation.expressions as expressions

    # Handle scalar or empty cases
    right = lib.item_from_zerodim(right)
    if lib.is_scalar(right) or np.ndim(right) == 0:
        # Handle scalar case by applying the operation on each column
        def column_op(a, b):
            if right is pd.NaT:
                return pd.Series([pd.NaT] * len(a), dtype='timedelta64[ns]')
            else:
                return func(a, b)

    elif isinstance(right, ABCDataFrame):
        assert right._indexed_same(left)
        def column_op(a, b):
            return func(a, b)

    elif isinstance(right, ABCSeries):
        if axis == "columns":
            # We only get here if called via left._combine_match_columns,
            # in which case we specifically want to operate row-by-row
            assert right.index.equals(left.columns)
            def column_op(a, b):
                return pd.Series([pd.NaT] * len(a), dtype='timedelta64[ns]')
        else:
            assert right.index.equals(left.index)  # Handle other cases later
            def column_op(a, b):
                return func(a, b)

    else:
        # Handle non-supported types
        raise NotImplementedError("Unsupported type for operation")

    # Evaluate the result with the defined operation
    new_data = expressions.evaluate(column_op, str_rep, left, right)
    return new_data
